def solve(df: pl.DataFrame) -> pl.DataFrame:
    numeric_cols = df.select(pl.all().is_numeric()).to_series().to_list()
    numeric_cols.sort()

    corr_matrix = df.select(pl.all().is_numeric()).corr()

    result_rows = []
    for i, col_i in enumerate(numeric_cols):
        row_data = [col_i]
        for j, col_j in enumerate(numeric_cols):
            if i == j:
                row_data.append(1.0)
            else:
                row_data.append(corr_matrix[col_i, col_j])
        result_rows.append(row_data)

    return pl.DataFrame(result_rows, schema=[pl.Series("cols", numeric_cols, dtype=pl.Utf8)] + [pl.Float64] * len(numeric_cols))

def solve(df: pl.DataFrame) -> pl.DataFrame:
    min_val = df["a"].min()
    max_val = df["a"].max()

    # Determine the smallest integer type that can hold the range
    if min_val == max_val:
        dtype = pl.Int8
    elif min_val >= -128 and max_val <= 127:
        dtype = pl.Int8
    elif min_val >= -32768 and max_val <= 32767:
        dtype = pl.Int16
    elif min_val >= -2147483648 and max_val <= 2147483647:
        dtype = pl.Int32
    else:
        dtype = pl.Int64

    return df.with_columns(pl.col("a").cast(dtype))

