def solve(df: pl.DataFrame) -> pl.DataFrame:
    # Check if column 'b' is entirely null
    b_all_null = df.select(pl.col("b").is_null().all()).item()
    # Check if column 'c' is entirely null
    c_all_null = df.select(pl.col("c").is_null().all()).item()

    # Select columns that are not entirely null, in the order b then c
    result_columns = []
    if not b_all_null:
        result_columns.append("b")
    if not c_all_null:
        result_columns.append("c")

    return df.select(result_columns)

def solve(df: pl.DataFrame) -> pl.DataFrame:
    # Identify columns that have at least one non-null value
    # sum(is_not_null()) > 0 means the column has at least one non-null
    cols_to_keep = df.select(pl.all().is_not_null().sum()).filter(pl.col(pl.Int64) > 0).columns

    # Reorder columns to start with 'b' then 'c', followed by other kept columns
    # We need to ensure 'b' and 'c' are first if they are in cols_to_keep
    ordered_cols = []
    for col in ['b', 'c']:
        if col in cols_to_keep:
            ordered_cols.append(col)

    # Add remaining columns in their original order
    for col in cols_to_keep:
        if col not in ordered_cols:
            ordered_cols.append(col)

    # Select the ordered columns
    return df.select(ordered_cols)

