def solve(df: pl.DataFrame) -> pl.DataFrame:
    def extract_and_transform(expr: pl.Expr) -> pl.Expr:
        # Extract the number from the string (assuming format "x: n")
        # .str.extract(r'(\d+)') captures the digits
        # .cast(pl.Int64) converts to integer
        # .apply(lambda x: -x if x % 2 == 0 else x) makes even numbers negative
        # .mul(5) multiplies by 5
        return (
            expr
            .str.extract(r'(\d+)')
            .cast(pl.Int64)
            .pipe(lambda x: x.apply(lambda v: -v if v % 2 == 0 else v))
            .mul(5)
        )

    return df.with_columns(udfs=extract_and_transform(pl.col("val"))).select("val", "udfs")

def solve(df: pl.DataFrame) -> pl.DataFrame:
    def process_udf(expr: pl.Expr) -> pl.Expr:
        # Extract numeric part, convert to int, check if even, negate if so, then multiply by 5
        return (
            expr
            .str.extract(r"(\d+)")
            .cast(pl.Int64)
            .pipe(lambda x: x * -1 if x % 2 == 0 else x)
            .pipe(lambda x: x * 5)
        )

    return df.with_columns(udfs=process_udf(pl.col("val")))

