def solve(df: pl.DataFrame) -> pl.DataFrame:
    patterns = ["winter", "disco", "onte", "discontent"]

    # Extract matches without allowing overlaps
    matches_no_overlap = df.with_columns(
        pl.col("values").str.extract_many(patterns, overlapping=False)
    )

    # Extract matches allowing overlaps
    matches_overlapping = df.with_columns(
        pl.col("values").str.extract_many(patterns, overlapping=True)
    )

    # Select columns in the required order: values, matches (non-overlapping), matches_overlapping
    return matches_no_overlap.join(
        matches_overlapping.select(["values", "matches"]),
        on="values",
        how="left"
    ).select(["values", "matches", "matches_overlapping"])

