            .map_elements(
                lambda ages: (
                    -1.0
                    * sum(
                        (count / total) * pl.lit(0).cast(pl.Float64).log()
                        if (count := pl.lit(0)) == 0
                        else (count / total) * pl.lit(0).cast(pl.Float64).log()
                    )
                    for count, total in zip(
                        pl.Series(ages).value_counts().to_series().to_list(),
                        [len(ages)]
                    )
                )
                if ages
                else 0.0
            ),
            return_dtype=pl.Float64,
        ).alias("age_entropy")
    )

