import polars as pl

def solve(df: pl.DataFrame) -> pl.DataFrame:
    avg = df.select(pl.col("values").mean())["values"].item()
    return df.select(
        pl.col("values").map_batches(lambda s: s - avg, return_dtype=pl.Float64).alias("values")
    )

