import polars as pl
import datetime as dt

def solve(df: pl.DataFrame) -> pl.DataFrame:
    start_date = dt.date(1982, 12, 31)
    end_date = dt.date(1996, 1, 1)

    return df.filter(
        (pl.col("birthdate") >= start_date) & 
        (pl.col("birthdate") <= end_date) & 
        (pl.col("height") > 1.7)
    ).select(["name", "birthdate", "weight", "height"])

def solve(df: pl.DataFrame) -> pl.DataFrame:
    return (
        df
        .with_columns(
            pl.col("birthdate").dt.year().alias("birth_year")
        )
        .with_columns(
            (pl.col("birth_year") // 10 * 10).alias("decade")
        )
        .group_by("decade")
        .agg(pl.len().alias("len"))
        .sort("decade")
    )

def solve(df: pl.DataFrame) -> pl.DataFrame:
    return (
        df
        .with_columns(
            pl.col("birthdate").dt.year().apply(lambda y: (y // 10) * 10).alias("decade")
        )
        .group_by("decade")
        .agg(pl.len().alias("len"))
        .sort("decade")
    )

def solve(df: pl.DataFrame) -> pl.DataFrame:
    return (
        df
        .with_columns(
            pl.col("birthdate").dt.year().div(10).mul(10).alias("decade")
        )
        .group_by("decade")
        .agg(
            pl.len().alias("sample_size"),
            pl.col("weight").mean().alias("avg_weight"),
            pl.col("height").max().alias("tallest")
        )
        .sort("decade")
    )

