import polars as pl

def solve(df: pl.DataFrame) -> pl.DataFrame:
    return (
        df
        .with_columns(
            pl.col("birthdate").dt.year().div(10).floor().cast(pl.Int64).alias("decade"),
            pl.col("name").str.split_exact(" ", 1).struct.field(0).alias("name")
        )
        .group_by("decade")
        .agg(
            pl.col("name").alias("name"),
            (pl.col("weight").mean() * 100).round(2) / 100.0.alias("avg_weight"),
            (pl.col("height").mean() * 100).round(2) / 100.0.alias("avg_height")
        )
        .sort("decade")
    )

def solve(df: pl.LazyFrame) -> pl.DataFrame:
    return (
        df
