def solve(df: pl.DataFrame) -> pl.DataFrame:
    return (
        df
        .with_columns(
            pl.col("time").dt.truncate("1h").alias("_lower_boundary"),
            (pl.col("time").dt.truncate("1h") + pl.duration(hours=1)).alias("_upper_boundary"),
        )
        .group_by(["groups", "_lower_boundary"])
        .agg(
            pl.col("time").alias("time"),
            pl.count().alias("len")
        )
        .select(["groups", "_lower_boundary", "_upper_boundary", "time", "len"])
    )

