def solve(df: pl.DataFrame) -> pl.DataFrame:
    return df.with_columns(
        pl.when(pl.all_horizontal(pl.col(["foo", "bar"]) < 2))
        .then(0)
        .otherwise(pl.col(["foo", "bar"]))
        .struct.unnest()
    )
